const fs=require('fs');
const liveness = fs.readFileSync('data/stale-liveness.tsv','utf8').split('\n').filter(Boolean);
const header = liveness[0].split('\t');
const map = {};
for (const line of liveness.slice(1)) {
  const cols = line.split('\t');
  map[cols[0]] = cols;
}
const urls = fs.readFileSync('triage-batch/s3.txt','utf8').split('\n').filter(Boolean).map(l=>l.split('|').pop().trim());
for (const u of urls) {
  const row = map[u];
  if (row) console.log(u, '=>', JSON.stringify(row));
  else console.log(u, '=> NOT FOUND');
}
"

