const fs=require('fs');
const c=require('crypto');
const lines = fs.readFileSync('triage-batch/s3.txt','utf8').split('\n').filter(Boolean);
for (const l of lines) {
  const num = l.split('.')[0];
  const u = l.split('|').pop().trim();
  const h = c.createHash('sha1').update(u).digest('hex').slice(0,16);
  console.log(num+'|'+h);
}
" > /tmp/idx.txt
cat /tmp/idx.txt

